const aliases=new Map();
for(const [theme,labels] of themeFamilies)for(const label of [theme,...labels.split(' ')])aliases.set(label,theme);
function themeKey(item){
 const label=item.name.split('ETF')[0];
 if(item.sector==='债券 ETF')return ['30年国债','5年地方债','科创债','可转债'].includes(label)?'债券/'+label:'债券/'+item.group;
 if(item.sector==='商品期货 ETF')return '期货/'+item.group;
 return aliases.get(label)||label;
}
const preferred=new Set(['sh510300','sh515450','sh515880','sz159835']);
const representative=new Map();
for(const item of instrumentCatalog.filter(i=>i.sector.endsWith('ETF'))){
 item.theme=themeKey(item);
 if(!representative.has(item.theme)||preferred.has(item.symbol))representative.set(item.theme,item.symbol);
}
export const instruments=instrumentCatalog.filter(i=>i.sector==='指数'||representative.get(i.theme)===i.symbol);
